// Browser extensions run their own scripts in the page; their errors are not the game's and must not stop it.
const foreignError68=(e,file='')=>/(chrome|moz|safari-web|ms-browser)-extension:\/\//.test(String(file)+' '+String(e?.stack||e?.message||e||''));
window.addEventListener('error',e=>{if(foreignError68(e.error||e.message,e.filename)){diagnostics.notes?.push?.('ignored extension error: '+String(e.message||'').slice(0,120));return;}fail(e.error||e.message);});
window.addEventListener('unhandledrejection',e=>{if(foreignError68(e.reason)){diagnostics.notes?.push?.('ignored extension rejection');return;}fail(e.reason);});
